'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import {
  type FileMetadata,
  type FileWithPreview,
  formatBytes,
  useFileUpload,
} from '@/registry/ndeko/hooks/use-file-upload';
import {
  CircleAlertIcon,
  FileArchiveIcon,
  FileIcon,
  FileSpreadsheetIcon,
  FileTextIcon,
  HeadphonesIcon,
  ImageIcon,
  Trash2Icon,
  UploadIcon,
  VideoIcon,
  XIcon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Progress } from '@/registry/ndeko/ui/progress';

const MAX_SIZE = 5 * 1024 * 1024;
const MAX_FILES = 6;

const FIRST_CHUNK_DELAY_MS = 100;
const MIN_CHUNK_BYTES = 2000;
const CHUNK_BYTES_SPREAD = 300000;
const MIN_CHUNK_DELAY_MS = 50;
const CHUNK_DELAY_SPREAD_MS = 450;
const CONGESTION_CHANCE = 0.05;
const CONGESTION_DELAY_MS = 500;
const FILLED_BAR_PAUSE_MS = 500;

const INITIAL_FILES: FileMetadata[] = [
  {
    name: 'q3-roadmap.zip',
    size: 252873,
    type: 'application/zip',
    url: '',
    id: 'q3-roadmap',
  },
  {
    name: 'cover-draft.png',
    size: 1528737,
    type: 'image/png',
    url: '',
    id: 'cover-draft',
  },
  {
    name: 'standup-notes.mp3',
    size: 1528737,
    type: 'audio/mpeg',
    url: '',
    id: 'standup-notes',
  },
];

const DOCUMENT_EXTENSIONS = ['.pdf', '.doc', '.docx'];
const ARCHIVE_EXTENSIONS = ['.zip', '.rar'];
const SPREADSHEET_EXTENSIONS = ['.xls', '.xlsx'];
const FILE_ICON_CLASS = 'size-4';

const DROP_ZONE = [
  'relative flex min-h-52 flex-col items-center overflow-hidden rounded-xl p-4 not-data-files:justify-center',
  'group hairline-border border-dashed border-foreground/20',
  'transition-[background-color,border-color,scale] duration-200 ease-(--ease-out-strong)',
  'data-dragging:scale-[1.01] motion-reduce:data-dragging:scale-100',
  'data-dragging:border-primary/50 data-dragging:bg-primary/[0.04]',
  'has-[input:focus-visible]:ring-[3px] has-[input:focus-visible]:ring-ring/25',
].join(' ');

const ICON_TILE =
  'keycap-3d text-muted-foreground mb-3 flex size-10 items-center justify-center rounded-full transition-transform duration-200 ease-(--ease-out-strong) group-data-dragging:-translate-y-0.5 motion-reduce:group-data-dragging:translate-y-0';

const ROW_ICON_TILE =
  'keycap-3d text-muted-foreground flex size-10 shrink-0 items-center justify-center rounded-lg';

const FILE_ROW =
  'bg-card hairline-ring ring-border flex flex-col rounded-xl p-2 pe-3 shadow-[0_1px_2px_rgb(0_0_0/0.04)]';

const COUNT =
  'keycap-3d inline-flex h-5 min-w-5 items-center justify-center rounded-[5px] px-1 text-[11px] font-medium tabular-nums text-muted-foreground';

const ENTER_TRANSITION: Transition = {
  duration: 0.2,
  ease: [0.23, 1, 0.32, 1],
};
const EXIT_TRANSITION: Transition = {
  duration: 0.15,
  ease: [0.23, 1, 0.32, 1],
};

const ITEM_VARIANTS: Variants = {
  hidden: { height: 0, opacity: 0, transition: EXIT_TRANSITION },
  shown: { height: 'auto', opacity: 1, transition: ENTER_TRANSITION },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0, transition: EXIT_TRANSITION },
  shown: { opacity: 1, transition: ENTER_TRANSITION },
};

type UploadProgress = {
  fileId: string;
  progress: number;
  completed: boolean;
};

function itemVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return ITEM_VARIANTS;
}

function presenceOf(isPresent: boolean) {
  if (isPresent) {
    return true;
  }
  return undefined;
}

function hasExtension(name: string, extensions: string[]) {
  return extensions.some((extension) => name.endsWith(extension));
}

function isDocument(type: string, name: string) {
  const isDocumentType = type.includes('pdf') || type.includes('word');
  const hasDocumentExtension = hasExtension(name, DOCUMENT_EXTENSIONS);
  return isDocumentType || hasDocumentExtension;
}

function isArchive(type: string, name: string) {
  const isArchiveType = type.includes('zip') || type.includes('archive');
  const hasArchiveExtension = hasExtension(name, ARCHIVE_EXTENSIONS);
  return isArchiveType || hasArchiveExtension;
}

function isSpreadsheet(type: string, name: string) {
  const isSpreadsheetType = type.includes('excel') || type.includes('xlsx');
  const hasSpreadsheetExtension = hasExtension(name, SPREADSHEET_EXTENSIONS);
  return isSpreadsheetType || hasSpreadsheetExtension;
}

function fileIconOf(file: File | FileMetadata) {
  const type = file.type;
  const name = file.name.toLowerCase();
  if (isDocument(type, name)) {
    return <FileTextIcon className={FILE_ICON_CLASS} />;
  }
  if (isArchive(type, name)) {
    return <FileArchiveIcon className={FILE_ICON_CLASS} />;
  }
  if (isSpreadsheet(type, name)) {
    return <FileSpreadsheetIcon className={FILE_ICON_CLASS} />;
  }
  if (type.startsWith('video/')) {
    return <VideoIcon className={FILE_ICON_CLASS} />;
  }
  if (type.startsWith('audio/')) {
    return <HeadphonesIcon className={FILE_ICON_CLASS} />;
  }
  if (type.startsWith('image/')) {
    return <ImageIcon className={FILE_ICON_CLASS} />;
  }
  return <FileIcon className={FILE_ICON_CLASS} />;
}

function nextChunkDelay() {
  const spread = Math.random() * CHUNK_DELAY_SPREAD_MS;
  const delay = Math.floor(spread);
  const isCongested = Math.random() < CONGESTION_CHANCE;
  if (isCongested) {
    return MIN_CHUNK_DELAY_MS + delay + CONGESTION_DELAY_MS;
  }
  return MIN_CHUNK_DELAY_MS + delay;
}

function simulateUpload(
  totalBytes: number,
  onProgress: (progress: number) => void,
  onComplete: () => void
) {
  let timeoutId = 0;
  let uploadedBytes = 0;
  let lastReportedProgress = 0;

  function sendChunk() {
    const spread = Math.random() * CHUNK_BYTES_SPREAD;
    const chunkSize = Math.floor(spread);
    const sentBytes = uploadedBytes + MIN_CHUNK_BYTES + chunkSize;
    uploadedBytes = Math.min(totalBytes, sentBytes);
    const sentShare = uploadedBytes / totalBytes;
    const progress = Math.floor(sentShare * 100);
    if (progress > lastReportedProgress) {
      lastReportedProgress = progress;
      onProgress(progress);
    }
    if (uploadedBytes < totalBytes) {
      timeoutId = window.setTimeout(sendChunk, nextChunkDelay());
      return;
    }
    timeoutId = window.setTimeout(onComplete, FILLED_BAR_PAUSE_MS);
  }

  timeoutId = window.setTimeout(sendChunk, FIRST_CHUNK_DELAY_MS);

  return () => window.clearTimeout(timeoutId);
}

function withProgress(
  items: UploadProgress[],
  fileId: string,
  changes: Partial<UploadProgress>
) {
  return items.map((item) => {
    if (item.fileId !== fileId) {
      return item;
    }
    return { ...item, ...changes };
  });
}

function isUploadingOf(fileProgress: UploadProgress | undefined) {
  if (!fileProgress) {
    return false;
  }
  return !fileProgress.completed;
}

export default function FileUpload13() {
  const shouldReduceMotion = useReducedMotion();
  const itemVariants = itemVariantsOf(shouldReduceMotion);
  const [uploadProgress, setUploadProgress] = useState<UploadProgress[]>([]);
  const cancelUploadsRef = useRef(new Map<string, () => void>());

  useEffect(() => {
    const cancelUploads = cancelUploadsRef.current;
    return () => {
      cancelUploads.forEach((cancel) => cancel());
      cancelUploads.clear();
    };
  }, []);

  function startUploads(addedFiles: FileWithPreview[]) {
    const newItems = addedFiles.map((file) => ({
      fileId: file.id,
      progress: 0,
      completed: false,
    }));
    setUploadProgress((current) => [...current, ...newItems]);

    addedFiles.forEach((file) => {
      const cancel = simulateUpload(
        file.file.size,
        (progress) => {
          setUploadProgress((current) =>
            withProgress(current, file.id, { progress })
          );
        },
        () => {
          cancelUploadsRef.current.delete(file.id);
          setUploadProgress((current) =>
            withProgress(current, file.id, { completed: true })
          );
        }
      );
      cancelUploadsRef.current.set(file.id, cancel);
    });
  }

  const [
    { files, isDragging, errors },
    {
      handleDragEnter,
      handleDragLeave,
      handleDragOver,
      handleDrop,
      openFileDialog,
      removeFile,
      clearFiles,
      getInputProps,
    },
  ] = useFileUpload({
    multiple: true,
    maxFiles: MAX_FILES,
    maxSize: MAX_SIZE,
    initialFiles: INITIAL_FILES,
    onFilesAdded: startUploads,
  });

  const hasFiles = files.length > 0;
  const firstError = errors[0];

  function removeUpload(fileId: string) {
    const cancel = cancelUploadsRef.current.get(fileId);
    cancel?.();
    cancelUploadsRef.current.delete(fileId);
    setUploadProgress((current) =>
      current.filter((item) => item.fileId !== fileId)
    );
    removeFile(fileId);
  }

  function removeAllUploads() {
    cancelUploadsRef.current.forEach((cancel) => cancel());
    cancelUploadsRef.current.clear();
    setUploadProgress([]);
    clearFiles();
  }

  return (
    <div className='flex w-full flex-col gap-2'>
      <div
        onDragEnter={handleDragEnter}
        onDragLeave={handleDragLeave}
        onDragOver={handleDragOver}
        onDrop={handleDrop}
        data-dragging={presenceOf(isDragging)}
        data-files={presenceOf(hasFiles)}
        className={DROP_ZONE}
      >
        <input
          {...getInputProps()}
          className='sr-only'
          aria-label='Upload files'
        />
        {hasFiles && (
          <div className='flex w-full flex-col gap-3'>
            <div className='flex items-center justify-between gap-2'>
              <h3 className='flex items-center gap-2 text-[13px] font-medium'>
                Files
                <span className={COUNT}>{files.length}</span>
              </h3>
              <div className='flex gap-2'>
                <Button variant='outline' size='sm' onClick={openFileDialog}>
                  <UploadIcon className='-ms-0.5 size-3.5 opacity-60' />
                  Add files
                </Button>
                <Button variant='outline' size='sm' onClick={removeAllUploads}>
                  <Trash2Icon className='-ms-0.5 size-3.5 opacity-60' />
                  Remove all
                </Button>
              </div>
            </div>
            <div className='-my-1 flex w-full flex-col'>
              <AnimatePresence initial={false}>
                {files.map((file) => {
                  const fileProgress = uploadProgress.find(
                    (item) => item.fileId === file.id
                  );
                  const isUploading = isUploadingOf(fileProgress);
                  const progress = fileProgress?.progress ?? 0;

                  return (
                    <motion.div
                      key={file.id}
                      className='-mx-1 overflow-hidden px-1 py-1'
                      variants={itemVariants}
                      initial='hidden'
                      animate='shown'
                      exit='hidden'
                    >
                      <div
                        data-uploading={presenceOf(isUploading)}
                        className={FILE_ROW}
                      >
                        <div className='flex items-center justify-between gap-2'>
                          <div className='flex items-center gap-3 overflow-hidden transition-opacity duration-300 in-data-uploading:opacity-50'>
                            <div className={ROW_ICON_TILE} aria-hidden='true'>
                              {fileIconOf(file.file)}
                            </div>
                            <div className='flex min-w-0 flex-col gap-0.5'>
                              <p className='truncate text-[13px] font-medium'>
                                {file.file.name}
                              </p>
                              <p className='text-muted-foreground text-xs tabular-nums'>
                                {formatBytes(file.file.size)}
                              </p>
                            </div>
                          </div>
                          <Button
                            size='icon'
                            variant='ghost'
                            className='text-muted-foreground hover:text-foreground -me-2'
                            onClick={() => removeUpload(file.id)}
                            aria-label={`Remove ${file.file.name}`}
                          >
                            <XIcon />
                          </Button>
                        </div>
                        <AnimatePresence initial={false}>
                          {isUploading && (
                            <motion.div
                              key='progress'
                              className='overflow-hidden'
                              variants={itemVariants}
                              initial='hidden'
                              animate='shown'
                              exit='hidden'
                            >
                              <Progress
                                value={progress}
                                aria-label={`Uploading ${file.file.name}`}
                                className='flex-row-reverse items-center gap-2 pt-2'
                              >
                                <span
                                  className='text-muted-foreground w-10 shrink-0 text-right text-xs tabular-nums'
                                  aria-hidden='true'
                                >
                                  {progress}%
                                </span>
                              </Progress>
                            </motion.div>
                          )}
                        </AnimatePresence>
                      </div>
                    </motion.div>
                  );
                })}
              </AnimatePresence>
            </div>
          </div>
        )}
        {!hasFiles && (
          <div className='flex flex-col items-center justify-center px-4 py-3 text-center'>
            <div className={ICON_TILE} aria-hidden='true'>
              <ImageIcon className='size-4' />
            </div>
            <p className='mb-1 text-[13px] font-medium'>Drop your files here</p>
            <p className='text-muted-foreground text-xs tabular-nums'>
              Max {MAX_FILES} files · Up to {formatBytes(MAX_SIZE)}
            </p>
            <Button variant='outline' className='mt-4' onClick={openFileDialog}>
              <UploadIcon className='-ms-1 opacity-60' />
              Select files
            </Button>
          </div>
        )}
      </div>
      {firstError && (
        <p
          role='alert'
          className='text-destructive-ink flex items-center gap-1.5 text-xs'
        >
          <CircleAlertIcon className='size-3.5 shrink-0' />
          <span>{firstError}</span>
        </p>
      )}
    </div>
  );
}
